// ---------- Helpers Supabase génériques (silencieux si pas configuré) ----------
// Chaque appel est "fire-and-forget" : l'interface reste instantanée (mise à
// jour locale immédiate), la synchro backend se fait en arrière-plan.
const dbInsert = (table, row) => {
  if (!isSupabaseConfigured) return;
  supabase.from(table).insert(row).then(({ error }) => { if (error) console.warn(`[${table}] insert`, error.message); });
};
const dbDelete = (table, match) => {
  if (!isSupabaseConfigured) return;
  let q = supabase.from(table).delete();
  Object.entries(match).forEach(([k, v]) => { q = q.eq(k, v); });
  q.then(({ error }) => { if (error) console.warn(`[${table}] delete`, error.message); });
};
const dbUpdateProfile = (userId, fields) => {
  if (!isSupabaseConfigured || !userId) return;
  supabase.from("profiles").update(fields).eq("id", userId).then(({ error }) => { if (error) console.warn("[profiles] update", error.message); });
};

