// ---------- Système XP / Niveaux culturels ----------
const LEVEL_NAMES = {
  fr: [[1, "Curieux"], [5, "Amateur"], [10, "Passionné"], [20, "Connaisseur"], [30, "Expert"], [50, "Mémoire vivante"]],
  ln: [[1, "Moto ya mposa"], [5, "Molingami"], [10, "Molingi makasi"], [20, "Moyebi"], [30, "Expert"], [50, "Bokundoli ya bomoi"]],
  en: [[1, "Curious"], [5, "Fan"], [10, "Enthusiast"], [20, "Connoisseur"], [30, "Expert"], [50, "Living Memory"]],
  nl: [[1, "Nieuwsgierige"], [5, "Fan"], [10, "Liefhebber"], [20, "Kenner"], [30, "Expert"], [50, "Levend Geheugen"]],
};
const XP_PER_LEVEL = 120; // XP nécessaire par niveau
const getLevelInfo = (xp, lang) => {
  const number = Math.max(1, Math.floor(xp / XP_PER_LEVEL) + 1);
  const names = LEVEL_NAMES[lang];
  let name = names[0][1];
  for (const [threshold, label] of names) if (number >= threshold) name = label;
  const xpIntoLevel = xp % XP_PER_LEVEL;
  const pct = Math.round((xpIntoLevel / XP_PER_LEVEL) * 100);
  return { number, name, xpIntoLevel, xpForNext: XP_PER_LEVEL, pct };
};

