// ---------- Small building blocks ----------
const Chip = ({ selected, onClick, children }) => (
  <div onClick={onClick} className={`chip${selected ? " selected" : ""}`}>{children}</div>
);

const CardActions = ({ id, title, sub, icon, favorites, toggleFav, shareItem, row }) => {
  const liked = favorites.some((f) => f.id === id);
  return (
    <div className="card-actions" style={row ? { flexDirection: "row", position: "absolute", top: 12, right: 12 } : {}} onClick={(e) => e.stopPropagation()}>
      <div className={`act-btn${liked ? " liked" : ""}`} onClick={() => toggleFav(id, title, sub, icon)}>
        <Heart size={16} strokeWidth={2} fill={liked ? "currentColor" : "none"} />
      </div>
      <div className="act-btn" onClick={() => shareItem(title)}><Share2 size={15} strokeWidth={2} /></div>
    </div>
  );
};

const NavBar = ({ screen, go, t }) => (
  <div className="navbar">
    <div className={`nav-item${screen === "home" ? " active" : ""}`} onClick={() => go("home")}><span className="nav-icon"><Home size={19} strokeWidth={2} /></span>{t.nav_home}</div>
    <div className={`nav-item${screen === "podcasts" || screen === "player" || screen === "articles" || screen === "article" ? " active" : ""}`} onClick={() => go("podcasts")}><span className="nav-icon"><Compass size={19} strokeWidth={2} /></span>{t.nav_discover}</div>
    <div className="nav-item central" onClick={() => go("create")}><div className="nav-fab"><Plus size={22} strokeWidth={2.5} /></div></div>
    <div className={`nav-item${screen === "amis" || screen === "conversation" ? " active" : ""}`} onClick={() => go("amis")}><span className="nav-icon"><Users size={19} strokeWidth={2} /></span>{t.nav_comm}</div>
    <div className={`nav-item${screen === "profil" || screen === "social" ? " active" : ""}`} onClick={() => go("profil")}><span className="nav-icon"><User size={19} strokeWidth={2} /></span>{t.nav_prof}</div>
  </div>
);

const BackBtn = ({ onClick, label }) => (
  <span className="back" onClick={onClick} style={{ display: "inline-flex", alignItems: "center", gap: 4 }}>
    <ArrowLeft size={14} strokeWidth={2.5} /> {label}
  </span>
);

const Header = ({ title, sub, withLogo = true, icons }) => (
  <div className="header">
    {withLogo && <Logo />}
    <div><div className="htitle">{title}</div><div className="hsub">{sub}</div></div>
    {icons}
  </div>
);

